  '战役：击败任意一位{name}大将': 'キャンペーン：{name}の大将をひとり倒す',
  '自由对局：用四国各在一场对局中击败电脑（已完成 {a}/{b}）': 'フリー対戦：四か国それぞれでCPUに1回勝利（{a}/{b}達成）',
  '还需 {n} 研究点': '研究ポイントあと{n}',
  '还需 {n} 点': 'あと{n}ポイント',
  '再积累 {n} 研究点可解锁「{name}」': 'あと{n}ポイントで「{name}」を解放できる',
  '已占有全部闸房，停止涨水': '水門小屋をすべて確保、増水が止まる',
  '对其他阵营的看法': '他陣営をどう見ているか',
