// ── 故事与战役（lore.js、campaign.js）及改名后重新对齐的条目 ──由 tools/i18n-story.js merge 回填，固定台词见 tools/I18N-GLOSSARY.md
AWI18n.add('ja', {
  '收购。开个价，车归我了。': '買収。値はつけました。その車両、いただきます。',
  '射程 3–6，只能攻击航空单位，伤害极高。移动后不可攻击。': '射程3–6。航空ユニットのみ攻撃でき、ダメージは極めて高い。移動後は攻撃不可。',
  '只能攻击航空单位，用于争夺制空权。': '航空ユニットのみ攻撃できる。制空権の確保に使う。',
  '只能攻击舰船，擅长攻击战列舰。航空单位和战列舰不可攻击潜艇。不敌驱逐舰。': '艦船のみ攻撃でき、戦艦への攻撃が得意。航空ユニットと戦艦は潜水艦を攻撃不可。駆逐艦には弱い。',
  '只能在道路、桥梁和建筑上移动。射程 1–3，移动后只能攻击相邻目标。可搭载 2 个徒步的步兵类单位（摩托兵除外）。攻击与防御介于中型坦克和重型坦克之间。': '道路・橋・拠点のマスのみ移動できる。射程1–3、移動後は隣接する目標のみ攻撃できる。徒歩の歩兵系ユニット（バイク兵を除く）を2体搭載できる。攻撃と防御は中戦車と重戦車の中間。',
  '隐形的航空单位：敌方只有相邻时才能发现（迷雾关闭时也有效）。对航空单位伤害高，对陆上单位伤害中等。': 'ステルス航空ユニット。敵軍は隣接時のみ発見できる（索敵オフ時も有効）。航空ユニットへのダメージが高く、地上ユニットへのダメージは中程度。',
  '射程 2–5 的舰船，移动后不可攻击。上一个己方回合没有攻击时处于下潜状态：敌方只有相邻时才能发现（迷雾关闭时也有效）。': '射程2–5の艦船。移動後は攻撃不可。前の自軍ターンに攻撃しなかった場合は潜航状態になり、敵軍は隣接時のみ発見できる（索敵オフ時も有効）。',
  '陆上单位结束移动停在这一格时拾取，获得 1–3 份陨星碎片（每个碎片堆在开局时随机决定），这一格变为碎片坑（与荒地相同）。轮式车辆的移动消耗为 3。': '地上ユニットがこのマスで移動を終えると拾い、隕星のかけら1–3個を得る（かけらの山ごとに対戦開始時にランダムで決まる）。このマスはかけらの穴になる（荒地と同じ）。タイヤ車両の移動コストは3。',
  '迷雾开启时，森林中的单位只有相邻时才会被发现。': '索敵オン時、森にいるユニットは隣接時のみ発見される。',
  '只有步兵类单位可以进入。狙击手、投弹手在山地上射程 +1。迷雾开启时，步兵类单位在山地上视野 +3。': '歩兵系ユニットのみ進入できる。狙撃兵・擲弾兵は山で射程+1。索敵オン時、歩兵系ユニットは山で視界+3。',
  '登陆艇可以进入。陆上单位可以在这里搭乘登陆艇；登陆艇可以在这里把搭载的单位卸载到相邻的格子。': '揚陸艇が進入できる。地上ユニットはここで揚陸艇に搭乗できる。揚陸艇はここで搭載ユニットを隣接マスに降ろせる。',
  '只有舰船可以进入，移动消耗 2，地形防御 2 星。': '艦船のみ進入でき、移動コスト2、地形防御★2。',
  '每回合提供 3 研究点（每个阵营最多计 3 座）。停留的己方步兵类单位每回合恢复 2 HP（需支付资金）。可以在这里研究科技。': '毎ターン研究ポイント3を得る（1陣営につき3か所まで有効）。ここにいる自軍の歩兵系ユニットは毎ターン2 HP回復する（資金が必要）。ここで技術研究ができる。',
  '这一局没有开启科技': 'この対戦では技術が無効',
  '这一局关闭了指挥官特长': 'この対戦では指揮官特長が無効',
  '这一局关闭了指挥官技能': 'この対戦では指揮官スキルが無効',
  '和「{name}」只能选一个': '「{name}」とはどちらか一方のみ選べる',
  '要先解锁「{name}」': '先に「{name}」を解放すること',
  '只能在己方回合解锁科技': '技術の解放は自軍ターンのみ',
  '这项科技不在己方的科技树里': 'この技術は自軍の技術ツリーにない',
  '这项科技已解锁': 'この技術は解放済み',
  '这里不能生产这个兵种': 'ここではこの兵種を生産できない',
  '这一格有单位': 'このマスにはユニットがいる',
  '这座建筑本回合已经生产过了': 'この拠点はこのターン生産済',
  '全军立即恢复 2 HP。己方下回合开始前：全军防御 +20%。': '全軍が即座に2 HP回復する。次の自軍ターン開始まで：全軍の防御+20%。',
  '立即获得「己方建筑数 × 80」的资金，再加回合收入的 20%。': '即座に「自軍拠点数 × 80」の資金を得て、さらにターン収入の20%を得る。',
  '所有敌方单位各损失 1 HP（不会被击毁）。有两个敌方阵营时各 0.8 HP，三个时各 0.7 HP。本回合：己方远程单位攻击 +30%。': '敵ユニットすべてが各1 HP減少する（撃破はされない）。敵が2陣営なら各0.8 HP、3陣営なら各0.7 HP。このターン：自軍の間接攻撃ユニットの攻撃+30%。',
  '全军立即恢复 2 HP（舰船 3 HP）。本回合：全军移动力 +1（舰船 +2），舰船对陆上单位伤害 +30%。己方下回合开始前：全军防御 +10%。': '全軍が即座に2 HP回復する（艦船は3 HP）。このターン：全軍の移動力+1（艦船は+2）、艦船の地上ユニットへのダメージ+30%。次の自軍ターン開始まで：全軍の防御+10%。',
  '本回合：航空单位移动力 +2、攻击 +50%，攻击时不受反击。其他单位移动力 +2、攻击 +30%。': 'このターン：航空ユニットは移動力+2、攻撃+50%、攻撃時に反撃を受けない。その他のユニットは移動力+2、攻撃+30%。',
  '本回合：各型坦克移动力 +2、攻击 +50%，攻击后可再移动。己方下回合开始前：各型坦克防御 +20%。': 'このターン：軽戦車・中戦車・重戦車は移動力+2、攻撃+50%、攻撃後に再移動できる。次の自軍ターン開始まで：軽戦車・中戦車・重戦車の防御+20%。',
  '最多 4 座没有单位的己方城市各出现一个满 HP 的步兵，当回合可行动。本回合：步兵类单位攻击 +30%、移动力 +1。': 'ユニットのいない自軍の都市最大4か所に、HP最大の歩兵が1体ずつ出現し、そのターンに行動できる。このターン：歩兵系ユニットの攻撃+30%、移動力+1。',
  '本回合：全军攻击 +20%。己方下回合开始前：敌方单位视野降为 1。迷雾关闭时，敌方只能发现自己单位 2 格内的己方单位。': 'このターン：全軍の攻撃+20%。次の自軍ターン開始まで：敵ユニットの視界が1になる。索敵オフ時、敵軍は自身のユニットから2マス以内の自軍ユニットのみ発見できる。',
  '本回合：全军移动力 +2，攻击时不受反击。': 'このターン：全軍の移動力+2、攻撃時に反撃を受けない。',
  '己方下回合开始前：己方反击伤害 ×2，全军防御 +20%。': '次の自軍ターン開始まで：自軍の反撃ダメージ×2、全軍の防御+20%。',
  '己方下回合开始前：敌方单位移动力 −3（最低 1）、视野 −2，己方全军防御 +20%。': '次の自軍ターン開始まで：敵ユニットの移動力−3（最低1）、視界−2、自軍は全軍の防御+20%。',
  '本回合：HP 未满的己方单位攻击 +50%，全军移动力 +1。': 'このターン：HPが最大でない自軍ユニットは攻撃+50%、全軍の移動力+1。',
  '本回合：全军攻击 +20%（舰船 +40%）、移动力 +2。己方下回合开始前：敌方舰船移动力 −3（最低 1），不能在港口修理。': 'このターン：全軍の攻撃+20%（艦船は+40%）、移動力+2。次の自軍ターン開始まで：敵艦船の移動力−3（最低1）、港での修理不可。',
  '己方下回合开始前：敌方单位在道路、桥梁上的移动消耗 +2（航空单位除外）。本回合：己方车辆攻击 +30%。': '次の自軍ターン開始まで：敵ユニットの道路・橋での移動コスト+2（航空ユニットを除く）。このターン：自軍車両の攻撃+30%。',
  '解锁黑潮后可查看。完成任意一组条件就能解锁：': '黒潮を解放すると見られる。いずれかの条件を満たせば解放される：',
  '所有阵营都能研究。': '全陣営が研究できる。',
  '两条科技线的第 3 级只能选一条。': '2系統のレベル3はどちらか一方だけ選べる。',
  '司令部被占领时，败北阵营的单位全部消失，建筑归占领方所有。全部单位被击毁时，这个阵营的建筑全部变为中立。': '司令部を占領された場合、敗北した陣営のユニットはすべて消え、拠点は占領した側のものになる。全ユニットを撃破された場合、その陣営の拠点はすべて中立になる。',
  '每座收入建筑每回合提供 {n} 资金，在回合开始时获得。这个数值可以在开局设置里调整。': '各収入拠点は毎ターン資金{n}を生み、ターン開始時に得る。この値は対戦開始前の設定で変更できる。',
  '把单位移动到同兵种、HP 未满的己方单位所在的格子，选择“合并”。': '同じ兵種でHPが最大でない自軍ユニットのいるマスへユニットを移動させ、「合流」を選ぶ。',
  '两个单位都是强化单位，合并后才保留强化。': '2ユニットとも強化ユニットのときだけ、合流後も強化が残る。',
  '攻击加成：位于己方{tower} 5 格范围内时 +10%，单位每 1 星 +5%，再加上指挥官的修正。': '攻撃ボーナス：自軍の{tower}から5マス以内にいると+10%、ユニットの★1つにつき+5%。さらに指揮官の補正を加える。',
  '攻击加成：单位每 1 星 +5%，再加上指挥官的修正。': '攻撃ボーナス：ユニットの★1つにつき+5%。さらに指揮官の補正を加える。',
  '防御加成：单位每 1 星 +5%，再加上指挥官的修正，最高 70%。': '防御ボーナス：ユニットの★1つにつき+5%、さらに指揮官の補正を加える。最大70%。',
  '受到不相邻的敌方单位攻击时不可反击。{list}受到相邻敌方单位攻击时也不可反击。': '隣接していない敵ユニットから攻撃を受けたときは反撃不可。{list}は、隣接する敵ユニットから攻撃を受けたときも反撃不可。',
  '不可攻击对方兵种的单位也不可反击。': '相手の兵種を攻撃できないユニットは反撃も不可。',
  '回合开始时，停留在己方建筑的单位恢复 2 HP，每恢复 1 HP 需支付造价 10% 的资金；资金不足时只恢复 1 HP。': 'ターン開始時、自軍拠点にいるユニットは2 HP回復する。1 HP回復するごとに価格の10%の資金が必要。資金が足りないときは1 HPのみ回復する。',
  '每座只能使用一次，敌我单位都受影响。运输单位搭载的单位不受影响。': '各サイロは一度しか使えず、敵味方どちらのユニットも影響を受ける。輸送ユニットに搭載されているユニットは影響を受けない。',
  '把单位移动到己方运输单位所在的格子就能搭载。友方的运输单位不能搭载己方单位。': 'ユニットを自軍の輸送ユニットのいるマスへ移動させると搭載される。友軍の輸送ユニットには自軍ユニットを搭載不可。',
  '攻击和受到攻击都能积累技能槽，积累量按损失的造价计算，受到攻击时是攻击时的 2 倍。': '攻撃しても攻撃を受けてもスキルゲージが蓄積する。蓄積量は失われた価格で計算し、攻撃を受けたときは攻撃したときの2倍。',
  '在己方{a}或{b}可以研究科技。': '自軍の{a}または{b}で技術研究ができる。',
  '在己方{a}可以研究科技。': '自軍の{a}で技術研究ができる。',
  '每个阵营可研究 6 条科技线：通用 3 条、阵营 2 条、指挥官 1 条。每条科技线分 3 级，要按顺序解锁。': '各陣営は6系統の技術を研究できる：共通3系統、陣営2系統、指揮官1系統。各系統は3レベルで、順番に解放する。',
  '解锁科技需要研究点。研究点在每回合开始时获得，可以一直攒着。': '技術の解放には研究ポイントが必要。研究ポイントは毎ターン開始時に入り、ためておける。',
  '研究点够一项科技所需的点数时，就能在己方回合立即解锁，当回合生效；一回合可以连续解锁多项。': '研究ポイントが技術に必要なポイントに届けば、自軍ターンにすぐ解放でき、そのターンから効果が出る。一ターンに続けていくつも解放できる。',
  '阵营 2 条科技线的第 3 级只能选一条。': '陣営の技術系統2本のレベル3は、どちらか一方のみ選べる。',
  '陆上单位结束移动停留在{shard}上就能拾取，获得 {min}–{max} 份（每个碎片堆在开局时随机决定），这一格变为{pit}。航空单位不拾取。': '地上ユニットが{shard}の上で移動を終えると拾い、{min}–{max}個を得る（かけらの山ごとに対戦開始時にランダムで決まる）。そのマスは{pit}になる。航空ユニットは拾わない。',
  '{name}已采完，变为山地': '{name}が枯渇し、山になった',
  '两个单位合并时，只要有一方是强化单位，合并后就是强化单位。双方都是强化单位时，返还其中一个单位的强化价。': '2つのユニットを合流させると、どちらかが強化ユニットなら合流後も強化ユニットになる。両方とも強化ユニットの場合、1体分の強化コストが返還される。',
  '可以在开局规则里关闭{res}。': '対戦開始前のルールで{res}をオフにできる。',
  '刚生产的单位，在做下一个动作之前可以按取消键撤回，资金和{res}全额返还。': '生産したばかりのユニットは、次の行動をする前ならキャンセルボタンで取り消せる。資金と{res}は全額戻る。',
  '单位移动后如果没有遇伏，也没有发现新的敌方单位，可以按取消键撤回这一步。': '移動後に待ち伏せされず、新しい敵ユニットも発見していなければ、キャンセルボタンでその移動を取り消せる。',
  '做了下一个动作之后不能撤回。': '次の行動をしたあとは取り消せない。',
  '迷雾开启时，只能看见己方和友方的单位、建筑周围的格子。': '索敵オン時、見えるのは自軍と友軍のユニット・拠点の周囲のマスのみ。',
  '位于{list}的单位（航空单位除外）处于隐蔽状态，只有相邻时才会被发现。': '{list}にいるユニット（航空ユニットを除く）は潜伏状態になり、隣接時のみ発見される。',
  '{sub}在任何位置都只有相邻时才会被发现，{dst}可以在 2 格内发现它。': '{sub}はどこにいても隣接時のみ発見される。{dst}は2マス以内で発見できる。',
  '{sub}在任何位置都只有相邻时才会被发现。': '{sub}はどこにいても隣接時のみ発見される。',
  '只能攻击看得见的目标。移动中遇到没有发现的敌方单位时停止移动（遇伏），这个单位本回合行动结束。': '攻撃できるのは見えている目標のみ。移動中に未発見の敵ユニットに出会うと移動が止まり（待ち伏せ）、そのユニットはそのターンの行動を終了する。',
  '每张地图有 2–4 个阵营，按{list}的顺序行动。各阵营可以各自为战，也可以结盟组队。': '各マップの陣営数は2–4で、{list}の順に行動する。各陣営は単独で戦うことも、同盟を組んでチームになることもできる。',
  '每张地图有 2–4 个阵营。各阵营可以各自为战，也可以结盟组队。': '各マップの陣営数は2–4。各陣営は単独で戦うことも、同盟を組んでチームになることもできる。',
  '战利品：三支及以上队伍对战时，击毁敌方单位可立即获得它造价 {pct}% 的资金。': '戦利品：三チーム以上の対戦では、敵ユニットを撃破すると即座にその価格の{pct}%の資金を得る。',
  '{name}阵营、指挥官和精锐兵种要解锁后才能在自由对局中使用。完成下面任意一组条件就能解锁。': '{name}の陣営・指揮官・精鋭兵種は、解放するとフリー対戦で使えるようになる。次のいずれかの条件を満たせば解放される。',
  '这一关的地图「{name}」还没做好。': 'このステージのマップ「{name}」はまだ完成していない。',
  '这一关的地图还没做好': 'このステージのマップはまだ完成していない',
  '这一关暂时不能开始': 'このステージは現在開始できない',
  '按任意键开始': 'いずれかのキーを押してスタート',
  '点击屏幕开始': '画面を押してスタート',
  '2–4 个阵营': '2–4陣営',
  '这张地图没有简介。': 'このマップには概要がない。',
  '这张地图暂时不能使用，请选择其他地图。': 'このマップは現在使えない。別のマップを選ぶこと。',
  '所有阵营都在同一队，至少要分成两队。': '全陣営が同じチームになっている。二チーム以上に分けること。',
  '完成任意一组条件就能解锁：': 'いずれかの条件を満たせば解放：',
  '开局时从这个阵营里随机选出一位指挥官。': '対戦開始時に、この陣営の指揮官から一人をランダムに選ぶ。',
  '这张地图的推荐设置：{list}': 'このマップの推奨設定：{list}',
  '对局进度会自动保存，可以在标题画面选“继续”接着进行。': '対戦の進行状況は自動で保存される。タイトル画面で「続ける」を選ぶと再開できる。',
  '每个提示都可以点击': '各ヒントは押して操作できる',
  '移动消耗都是 1': '移動コストすべて1',
  '开阔地形，陆上单位都能进入，地形防御 1 星。': '開けた地形。地上ユニットはすべて進入でき、地形防御★1。',
  '陆上单位的移动消耗都是 1，没有地形防御。': '地上ユニットの移動コストはすべて1。地形防御なし。',
  '跨越河流的道路，陆上单位的移动消耗都是 1，没有地形防御。': '川をまたぐ道路。地上ユニットの移動コストはすべて1。地形防御なし。',
  '徒步的步兵类单位可以进入，车辆和摩托兵不能进入。': '徒歩の歩兵系ユニットは進入できる。車両とバイク兵は進入不可。',
  '只有舰船和航空单位可以进入。': '艦船と航空ユニットのみ進入できる。',
  '地形防御 2 星，车辆的移动消耗是 2。': '地形防御★2。車両の移動コストは2。',
  '可以在这里研究科技。': 'ここで技術研究ができる。',
  '通关下面任意一关，同时解锁这位指挥官。': '下のステージをどれかクリアすると、この指揮官も解放される。',
  '电脑要在普通难度以上。': 'CPUは難易度ふつう以上にすること。',
  '要先解锁前一级': '前のレベルを先に解放すること',
  '研究点够一项科技所需的点数时就能立即解锁，一回合可以连续解锁多项。': '研究ポイントが技術に必要なポイントに届けばすぐ解放できる。一ターンに続けていくつも解放できる。',
  '现在不能解锁这项科技': '現在この技術は解放できない',
  '这张地图暂时不能使用（地图文件可能正在修改），请选择其他地图。': 'このマップは現在使えない（マップファイルが編集中の可能性がある）。別のマップを選ぶこと。',
  '这张地图需要 {n} 个阵营，现在不能开始对局，请选择其他地图。': 'このマップには{n}陣営が必要。現在は対戦を開始できない。別のマップを選ぶこと。',
  '这张地图暂时不能使用。': 'このマップは現在使えない。',
  '要返回标题吗？': 'タイトルへ戻る？',
  '要认输吗？': '降参する？',
  '要出售这个单位吗？': 'このユニットを売却する？',
  '还差{list}': 'あと{list}',
  '车辆移动力 +1。步兵类单位攻击 −10%。': '車両の移動力+1。歩兵系ユニットの攻撃−10%。',
  '位于 2 星及以上地形或建筑的单位防御 +20%。全军攻击 −10%。': '地形防御★2以上の地形または拠点にいるユニットの防御+20%。全軍の攻撃−10%。',
  '所有单位造价 −10%。全军攻击 −10%。': '全ユニットの価格−10%。全軍の攻撃−10%。',
  '自行火炮、火箭炮攻击 +40%。其他远程单位攻击 +20%。': '自走砲・ロケット砲の攻撃+40%。その他の間接攻撃ユニットの攻撃+20%。',
  '舰船攻击 +30%、防御 +20%、移动力 +1、造价 −15%，在港口修理免费。步兵类单位攻击 +10%。': '艦船の攻撃+30%、防御+20%、移動力+1、価格−15%、港での修理は無料。歩兵系ユニットの攻撃+10%。',
  '攻击机、轰炸机、战斗机攻击 +30%、造价 −20%。': '攻撃機・爆撃機・戦闘機の攻撃+30%、価格−20%。',
  '各型坦克攻击 +30%、防御 +10%。其他单位攻击 −15%。': '軽戦車・中戦車・重戦車の攻撃+30%、防御+10%。その他のユニットの攻撃−15%。',
  '步兵类单位攻击 +30%、防御 +10%、占领值 ×1.5、视野 +1。车辆造价 +10%。': '歩兵系ユニットの攻撃+30%、防御+10%、占領値×1.5、視界+1。車両の価格+10%。',
  '武装直升机攻击 +40%、防御 +20%、造价 −20%。运输直升机移动力 +2、搭载数 +1。舰船攻击和防御 −20%。': '戦闘ヘリの攻撃+40%、防御+20%、価格−20%。輸送ヘリの移動力+2、搭載数+1。艦船の攻撃と防御−20%。',
  '狙击手射程 +1、攻击 +40%、造价 −20%，移动后可攻击，击毁目标后可再行动（每回合一次）。投弹手攻击 +25%，其他步兵类单位攻击 +15%。全军视野 +1。位于森林、山地的己方单位防御 +15%。': '狙撃兵は射程+1、攻撃+40%、価格−20%、移動後に攻撃でき、目標を撃破すると再行動できる（毎ターン一回）。擲弾兵の攻撃+25%、その他の歩兵系ユニットの攻撃+15%。全軍の視界+1。森・山にいる自軍ユニットの防御+15%。',
  '新生产的单位当回合可行动。所有单位造价 +10%。': '新しく生産したユニットはそのターンに行動できる。全ユニットの価格+10%。',
  '直射单位攻击 +5%，攻击后可用剩余移动力再移动，但不能再攻击或占领。': '直接攻撃ユニットは攻撃+5%、攻撃後に残りの移動力で再移動できるが、再攻撃と占領は不可。',
  '己方单位每回合开始时恢复 1 HP，在建筑上修理免费。全军攻击 −10%。': '自軍ユニットは毎ターン開始時に1 HP回復し、拠点での修理は無料。全軍の攻撃−10%。',
  '己方单位被相邻的敌方单位攻击时先手反击：先反击，敌方再按剩余 HP 攻击。己方主动攻击时攻击 −10%。': '自軍ユニットは隣接する敵ユニットから攻撃を受けると先制反撃する：先に反撃し、その後に敵ユニットが残りHPで攻撃する。自分から攻撃するときは攻撃−10%。',
  '防空车、防空导弹、战斗机对航空单位伤害 +40%、视野 +2、造价 −25%。防空车对陆上单位伤害 +40%、防御 +15%、移动力 +1。直升机、攻击机、轰炸机攻击 −15%。': '対空戦車・対空ミサイル・戦闘機は航空ユニットへのダメージ+40%、視界+2、価格−25%。対空戦車は地上ユニットへのダメージ+40%、防御+15%、移動力+1。ヘリ・攻撃機・爆撃機の攻撃−15%。',
  '潜艇攻击 +40%、造价 −20%，只有相邻时才会被发现。驱逐舰、炮艇攻击 +20%、造价 −15%。步兵类单位攻击 +25%，车辆攻击 +10%。': '潜水艦は攻撃+40%、価格−20%、隣接時のみ発見される。駆逐艦・砲艇の攻撃+20%、価格−15%。歩兵系ユニットの攻撃+25%、車両の攻撃+10%。',
  '侦察车、摩托兵、运兵车移动力 +3。侦察车、摩托兵攻击 +60%，攻击后可用剩余移动力再移动。中型、重型坦克造价 +10%。': '偵察車・バイク兵・輸送車の移動力+3。偵察車・バイク兵は攻撃+60%、攻撃後に残りの移動力で再移動できる。中戦車・重戦車の価格+10%。',
  '喷火兵、破甲兵攻击 +50%、移动力 +1、造价 −20%。远程单位攻击 −10%。': '火炎放射兵・バズーカ兵の攻撃+50%、移動力+1、価格−20%。間接攻撃ユニットの攻撃−10%。',
  '己方单位在能进入的地形上移动消耗都是 1。步兵类单位移动力 +1。': '自軍ユニットは進入できる地形での移動コストがすべて1になる。歩兵系ユニットの移動力+1。',
  '己方单位的攻击不随 HP 减少而降低。修理费 ×2。': '自軍ユニットの攻撃はHPが減っても下がらない。修理費×2。',
  '己方城市也可以生产步兵类单位。步兵类单位造价 −20%、攻击 +10%。': '自軍の都市でも歩兵系ユニットを生産できる。歩兵系ユニットの価格−20%、攻撃+10%。',
  '各型坦克、深渊战车、装甲列车攻击 +15%。位于陨星矿、荒地、废墟的己方单位防御 +20%，每回合恢复 1 HP。己方陨星矿收入 +50%。': '軽戦車・中戦車・重戦車・深淵戦車・装甲列車の攻撃+15%。隕星鉱山・荒地・廃墟にいる自軍ユニットは防御+20%、毎ターン1 HP回復する。自軍の隕星鉱山の収入+50%。',
  '舰船攻击 +20%、移动力 +1。远程单位攻击 +15%。己方单位在沙滩上的移动消耗为 1。迷雾开启时，视野范围内海洋、沙滩、礁石上的敌方单位都可见，礁石的隐蔽对其无效（潜艇除外）。': '艦船の攻撃+20%、移動力+1。間接攻撃ユニットの攻撃+15%。自軍ユニットは砂浜の移動コストが1になる。索敵オン時、視界内の海・砂浜・岩礁にいる敵ユニットはすべて見え、岩礁による潜伏は無効になる（潜水艦を除く）。',
  '所有单位造价 −15%。每击毁一个敌方单位，获得它造价 30% 的资金。': '全ユニットの価格−15%。敵ユニットを一体撃破するたびに、その価格の30%の資金を得る。',
  '车辆攻击 +10%，在道路、桥梁上防御 +15%。回合开始时位于道路、桥梁的车辆本回合移动力 +2。装甲列车造价 −20%。': '車両の攻撃+10%、道路・橋では防御+15%。ターン開始時に道路・橋にいる車両は、そのターンの移動力+2。装甲列車の価格−20%。',
  '汀鹭的修理本来就免费，只有“额外恢复 1 HP”有效': '汀鷺の修理はもともと無料のため、「追加で1 HP回復」のみ有効',
  '每座兵工厂每回合可生产 2 个单位（要先把第一个单位移出建筑）；重型坦克造价 −20%。': '各工場で毎ターン2体生産できる（先に1体目を拠点の外へ移動させること）。重戦車の価格−20%。',
  '沧澜的舰船在港口修理本来就免费，只有“舰船造价 −10%”有效': '滄瀾の艦船は港での修理がもともと無料のため、「艦船の価格−10%」のみ有効',
  '步兵类单位在森林、山地、沼泽上的移动消耗都是 1。': '歩兵系ユニットは森・山・沼地での移動コストがすべて1になる。',
  '雪杉的单位在可进入地形上的移动消耗本来就都是 1': '雪杉のユニットは進入できる地形での移動コストがもともとすべて1',
  '每个己方回合开始时，己方城市、司令部、碉堡使相邻且可见的敌方单位各损失 1 HP（不会被击毁；每个单位每回合只受一次）。': '自軍ターンの開始時ごとに、自軍の都市・司令部・トーチカに隣接し、かつ見えている敵ユニットが各1 HP減少する（撃破はされない。1ユニットにつき毎ターン1回のみ）。',
  '侦察车、轻型坦克、防空车移动力再 +1。': '偵察車・軽戦車・対空戦車の移動力がさらに+1。',
  '运兵车移动力 +1、搭载数 +1。步兵类单位的攻击减益减为 −5%。': '輸送車の移動力+1、搭載数+1。歩兵系ユニットの攻撃ペナルティが−5%に軽くなる。',
  '强化技能「闪击」，其他效果保留。本回合：侦察车、防空车和各型坦克击毁目标后可再行动一次，全军最多 4 次。': 'スキル「電撃」を強化する。他の効果はそのまま。このターン：偵察車・対空戦車・軽戦車・中戦車・重戦車は目標を撃破するともう一度行動できる。全軍で最大4回。',
  '远程单位的运气范围变为 5–9（原来 0–9）。自行火炮、火箭炮视野 +2。': '間接攻撃ユニットの幸運の範囲が5–9になる（元は0–9）。自走砲・ロケット砲の視界+2。',
  '自行火炮移动后可以攻击距离 2 格的目标，这次攻击 −30%。': '自走砲は移動後、距離2マスの目標を攻撃できる。その攻撃は−30%。',
  '强化技能「炮火覆盖」，其他效果保留。本回合：己方远程单位射程 +1。': 'スキル「制圧砲撃」を強化する。他の効果はそのまま。このターン：自軍の間接攻撃ユニットの射程+1。',
  '各型坦克在森林、废墟、荒地上的移动消耗为 1。': '軽戦車・中戦車・重戦車は森・廃墟・荒地での移動コストが1になる。',
  '与己方坦克相邻的其他陆上单位，攻击和反击时没有攻击 −15% 的减益。': '自軍の戦車に隣接するその他の地上ユニットは、攻撃と反撃のとき攻撃−15%のペナルティを受けない。',
  '强化技能「履带洪流」，其他效果保留。发动时，最多 2 座没有单位的己方兵工厂各出现一辆 5 HP 的轻型坦克，当回合可行动。': 'スキル「鋼鉄の奔流」を強化する。他の効果はそのまま。発動時、ユニットのいない自軍の工場最大2か所に、5 HPの軽戦車が一両ずつ出現し、そのターンに行動できる。',
  '己方单位被敌方击毁时，返还它造价的 10%。': '自軍ユニットが敵軍に撃破されると、その価格の10%が戻る。',
  '强化技能「加班」，其他效果保留。本回合：单位造价 −40%，每座生产建筑可生产 3 次。': 'スキル「残業」を強化する。他の効果はそのまま。このターン：ユニットの価格−40%、各生産拠点で3回生産できる。',
  '主动攻击 HP 比自己低的敌方单位时，没有攻击 −10% 的减益。': '自分よりHPが低い敵ユニットに自分から攻撃するとき、攻撃−10%のペナルティを受けない。',
  '不发动技能时，喷火兵攻击后也会把目标所在的森林变为荒地。': 'スキルを発動していないときも、火炎放射兵が攻撃すると目標のいる森が荒地に変わる。',
  '强化技能「燎原」，其他效果保留。本回合：破甲兵攻击也有溅射。每个敌方单位每回合因溅射最多损失 5 HP。': 'スキル「燎原」を強化する。他の効果はそのまま。このターン：バズーカ兵の攻撃にも余波が発生する。余波による減少は敵ユニット一体につき毎ターン最大5 HP。',
  '舰船在礁石上的移动消耗为 1。位于礁石、港口的舰船防御 +10%。': '艦船の岩礁での移動コストが1になる。岩礁・港にいる艦船の防御+10%。',
  '登陆艇搭载数 +1。位于沙滩的己方陆上单位防御 +20%。': '揚陸艇の搭載数+1。砂浜にいる自軍の地上ユニットの防御+20%。',
  '强化技能「怒潮」，其他效果保留。本回合：战列舰移动后可以攻击，射程 2–4。': 'スキル「怒濤」を強化する。他の効果はそのまま。このターン：戦艦は移動後も攻撃でき、射程2–4。',
  '攻击机、轰炸机、战斗机也可以在己方城市修理。': '攻撃機・爆撃機・戦闘機は自軍の都市でも修理できる。',
  '强化技能「俯冲」，其他效果保留。己方下回合开始前：只有敌方战斗机、防空导弹、防空车能攻击己方攻击机、轰炸机、战斗机。': 'スキル「急降下」を強化する。他の効果はそのまま。次の自軍ターン開始まで：自軍の攻撃機・爆撃機・戦闘機を攻撃できるのは、敵の戦闘機・対空ミサイル・対空戦車のみ。',
  '直升机可以发现周围 8 格森林、废墟中的隐蔽单位。武装直升机对步兵类单位伤害 +10%。': 'ヘリは周囲8マスの森・廃墟にいる潜伏ユニットを発見できる。戦闘ヘリの歩兵系ユニットへのダメージ+10%。',
  '回合开始时已在运输直升机上的步兵类单位，卸载后当回合还能攻击或占领，但不能移动。': 'ターン開始時にすでに輸送ヘリに搭載されていた歩兵系ユニットは、降ろしたターンも攻撃または占領ができるが、移動は不可。',
  '强化技能「蜂群」，其他效果保留。本回合：武装直升机攻击时，目标每与一架己方直升机相邻，攻击 +10%，最多 +30%。': 'スキル「蜂の群れ」を強化する。他の効果はそのまま。このターン：戦闘ヘリの攻撃時、目標に隣接する自軍のヘリ一機につき攻撃+10%、最大+30%。',
  '回合开始时，HP 不高于 4 的单位多恢复 1 HP。': 'ターン開始時、HPが4以下のユニットは追加で1 HP回復する。',
  '满 HP 的己方单位没有攻击 −10% 的减益。': 'HP最大の自軍ユニットは攻撃−10%のペナルティを受けない。',
  '强化技能「急救」，其他效果保留。恢复量提高到 3 HP。复活最近被击毁的 2 个单位，各 4 HP。每个单位每局只能复活一次。': 'スキル「救急」を強化する。他の効果はそのまま。回復量が3 HPに上がる。最後に撃破された2体が各4 HPで復活する。復活は一ユニットにつき一対戦に一度まで。',
  '防空导弹射程 +1。防空车、防空导弹、战斗机视野再 +1。': '対空ミサイルの射程+1。対空戦車・対空ミサイル・戦闘機の視界がさらに+1。',
  '强化技能「天网」，其他效果保留。被“天网”攻击的敌方航空单位立即结束行动。': 'スキル「天網」を強化する。他の効果はそのまま。「天網」の攻撃を受けた敵の航空ユニットは即座に行動を終了する。',
  '上回合没有移动的潜艇，本回合第一次攻击 +20%。': '前のターンに移動しなかった潜水艦は、このターン最初の攻撃+20%。',
  '潜艇攻击后可用剩余移动力再移动。': '潜水艦は攻撃後、残りの移動力で再移動できる。',
  '强化技能「狼群」，其他效果保留。本回合：潜艇可以穿过敌方舰船所在的格子。': 'スキル「群狼」を強化する。他の効果はそのまま。このターン：潜水艦は敵艦船のいるマスを通過できる。',
  '强化技能「全民皆兵」，其他效果保留。出现步兵的城市增加到最多 6 座，步兵初始为 1 星。': 'スキル「総動員」を強化する。他の効果はそのまま。歩兵が出現する都市が最大6か所に増え、歩兵は最初から★1。',
  '投弹手击毁目标后也可再行动（每回合一次）。': '擲弾兵も目標を撃破すると再行動できる（毎ターン一回）。',
  '狙击手被相邻的敌方单位攻击时可以反击，伤害是正常的 50%。': '狙撃兵は隣接する敵ユニットから攻撃を受けると反撃でき、ダメージは通常の50%。',
  '强化技能「一击」，其他效果保留。本回合：每个狙击手击毁目标后可连续再行动，最多 3 次。': 'スキル「一撃」を強化する。他の効果はそのまま。このターン：各狙撃兵は目標を撃破するたびに続けて再行動できる。最大3回。',
  '敌方单位遇伏时，伏击它的己方单位先攻击一次，不受反击。每个己方单位每个敌方回合一次。': '敵ユニットが待ち伏せにあうと、待ち伏せた自軍ユニットが先に一度攻撃し、反撃を受けない。自軍ユニット一体につき、敵ターンごとに一度。',
  '强化技能「灯火管制」，其他效果保留。持续时间延长到 2 个敌方回合。迷雾关闭时，敌方只能发现相邻的己方单位。生效期间技能槽不积累。': 'スキル「灯火管制」を強化する。他の効果はそのまま。持続時間が敵ターン2回分に延びる。索敵オフ時、敵軍は隣接する自軍ユニットのみ発見できる。効果中はスキルゲージが蓄積しない。',
  '攻击后再移动时，剩余移动力 +1。': '攻撃後の再移動時、残りの移動力+1。',
  '攻击后再移动过的单位，己方下回合开始前防御 +15%。': '攻撃後に再移動したユニットは、次の自軍ターン開始まで防御+15%。',
  '强化技能「风驰」，其他效果保留。本回合：全军移动力提高到 +3，直射单位攻击后可用全部移动力再移动。': 'スキル「疾風」を強化する。他の効果はそのまま。このターン：全軍の移動力が+3に上がり、直接攻撃ユニットは攻撃後に移動力すべてを使って再移動できる。',
  '履带车辆可以进入河流，轮式车辆可以进入沼泽，移动消耗都是 2。': 'キャタピラ車両は川に、タイヤ車両は沼地に進入でき、移動コストはどちらも2。',
  '强化技能「寒潮」，其他效果保留。生效期间：敌方单位在森林、山地、荒地、沼泽、河流上的移动消耗 +1（航空单位除外）。': 'スキル「寒波」を強化する。他の効果はそのまま。効果中：敵ユニットは森・山・荒地・沼地・川での移動コスト+1（航空ユニットを除く）。',
  '己方单位的地形防御也不随 HP 减少而降低。': '自軍ユニットの地形防御もHPが減っても下がらない。',
  '每个敌方回合，第一个要被击毁的己方单位保留 1 HP。受攻击前 HP 至少为 5 才有效，每个单位每局一次。': '敵ターンごとに、撃破されるはずの最初の自軍ユニットが1 HPで残る。攻撃を受ける前のHPが5以上のときのみ有効。一ユニットにつき一対戦に一度。',
  '强化技能「背水」，其他效果保留。攻击加成改为每损失 1 HP +10%，最多 +90%。己方下回合开始前：“咬牙”每个敌方回合可触发 3 次。': 'スキル「背水」を強化する。他の効果はそのまま。攻撃ボーナスは、失った1 HPごとに+10%、最大+90%になる。次の自軍ターン開始まで：「食いしばり」は敵ターンごとに3回発動できる。',
  '位于己方建筑的单位每回合免费恢复 1 HP（航空单位除外）。': '自軍拠点にいるユニットは毎ターン無料で1 HP回復する（航空ユニットを除く）。',
  '位于 2 星及以上地形或建筑的单位反击时，没有攻击 −10% 的减益。': '地形防御★2以上の地形または拠点にいるユニットは、反撃時に攻撃−10%のペナルティを受けない。',
  '强化技能「铁壁」，其他效果保留。恢复量提高到 3 HP。己方下回合开始前：敌方的占领不会减少己方建筑的占领值。': 'スキル「鉄壁」を強化する。他の効果はそのまま。回復量が3 HPに上がる。次の自軍ターン開始まで：敵軍が占領しても自軍拠点の占領値は減らない。',
  '所有单位造价再 −5%，结果向下取整到 10 的倍数。': '全ユニットの価格がさらに−5%。結果は10の倍数に切り捨てる。',
  '回合开始时，每持有 500 资金获得 20 资金，最多 200（上限随地图规模变化）。': 'ターン開始時、所持資金500ごとに資金20を得る。最大200（上限はマップの規模で変わる）。',
  '强化技能「军费」，其他效果保留。每座建筑的资金提高到 100。本回合：单位造价再 −20%。': 'スキル「軍資金」を強化する。他の効果はそのまま。拠点一つあたりの資金が100に上がる。このターン：ユニットの価格がさらに−20%。',
  '运气范围变为 −5 至 +55（原来 0 至 +40）。': '幸運の範囲が−5～+55になる（元は0～+40）。',
  '强化技能「梭哈」，其他效果保留。本回合：运气范围 ×1.5。': 'スキル「オールイン」を強化する。他の効果はそのまま。このターン：幸運の範囲×1.5。',
  '侦察车可以占领建筑，占领值减半。不能使用导弹井。': '偵察車は拠点を占領でき、占領値は半減する。ミサイルサイロは使用不可。',
  '强化技能「穿插」，其他效果保留。被侦察车、摩托兵、运兵车穿过的敌方陆上单位各损失 1 HP（不会被击毁），每回合最多 2 HP。': 'スキル「浸透」を強化する。他の効果はそのまま。偵察車・バイク兵・輸送車に通過された敵の地上ユニットが各1 HP減少する（撃破はされない）。毎ターン最大2 HP。',
  '己方单位正在占领的敌方建筑，本回合不给敌方提供收入。': '自軍ユニットが占領中の敵拠点は、そのターン敵軍に収入を与えない。',
  '强化技能「加征」，其他效果保留。获得的收入提高到 150%。本回合：占领中立建筑时占领值 ×2。': 'スキル「追徴」を強化する。他の効果はそのまま。得る収入が150%に上がる。このターン：中立拠点を占領するとき占領値×2。',
  '己方城市还可以生产侦察车和运兵车。': '自軍の都市で偵察車と輸送車も生産できる。',
  '不发动技能时，每回合也可以出售 1 个位于己方建筑的单位，返还造价的 40%。': 'スキルを発動していないときも、自軍拠点にいるユニットを毎ターン1体売却でき、価格の40%が戻る。',
  '强化技能「黑市」，其他效果保留。本回合：在己方城市生产的单位当回合可行动。': 'スキル「闇市」を強化する。他の効果はそのまま。このターン：自軍の都市で生産したユニットはそのターンに行動できる。',
});

